Looking at this problem, I need to:
1. Parse the manifest to get pairs (rule_id::entity) and facts per rule
2. Load the usaspending_awards.json file and index awards by `generated_unique_award_id`
3. For each pair, extract the relevant fields based on the decision rules
4. Handle ABSENT (null/missing), CONFLICT (multiple records with different values), and normal cases

The decision rules map:
- `usa.period_3y` → `performance start` from `period_of_performance.start_date`, `performance end` from `period_of_performance.end_date`
- `usa.obligated_95` → `amount obligated` from `total_obligation`, `potential value` from `base_and_all_options`

Dates should be YYYY-MM-DD, amounts as decimal strings.

```python
import json
import os
import sys

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    awards_path = os.path.join(packet_dir, "usaspending_awards.json")
    with open(awards_path) as f:
        awards = json.load(f)

    awards_by_id = {}
    for award in awards:
        guid = award.get("generated_unique_award_id")
        if guid:
            awards_by_id.setdefault(guid, []).append(award)

    def extract_fact(rule_id, fact, award):
        if rule_id == "usa.period_3y":
            pop = award.get("period_of_performance") or {}
            if fact == "performance start":
                return pop.get("start_date")
            elif fact == "performance end":
                return pop.get("end_date")
        elif rule_id == "usa.obligated_95":
            if fact == "amount obligated":
                return award.get("total_obligation")
            elif fact == "potential value":
                return award.get("base_and_all_options")
        return None

    def format_value(rule_id, fact, value):
        if rule_id == "usa.period_3y":
            if isinstance(value, str):
                return value[:10]
            return str(value)[:10]
        elif rule_id == "usa.obligated_95":
            return str(value)
        return str(value)

    result = {}

    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        facts = manifest["facts"][rule_id]
        fact_results = {}
        matching_awards = awards_by_id.get(entity, [])

        for fact in facts:
            values = []
            for award in matching_awards:
                value = extract_fact(rule_id, fact, award)
                if value is not None:
                    values.append(value)

            if len(values) == 0:
                fact_results[fact] = "ABSENT"
            else:
                formatted_values = [format_value(rule_id, fact, v) for v in values]
                if len(set(formatted_values)) == 1:
                    fact_results[fact] = [formatted_values[0], "usaspending_awards"]
                else:
                    fact_results[fact] = "CONFLICT"

        result[pair] = fact_results

    print(json.dumps(result))

main()
