import sys
import os
import json
from decimal import Decimal

def get_field(record, path):
    """Traverse a nested dict using a tuple of keys."""
    cur = record
    for key in path:
        if isinstance(cur, dict):
            cur = cur.get(key)
        else:
            return None
    return cur

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    # Load the awards file (document name is fixed by the decision rules)
    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    awards = []
    if os.path.exists(awards_file):
        with open(awards_file) as f:
            awards = json.load(f)

    # Index awards by generated_unique_award_id
    index = {}
    for award in awards:
        eid = award.get("generated_unique_award_id")
        if eid is not None:
            index.setdefault(eid, []).append(award)

    # Mapping from rule_id + fact name to the JSON path that establishes the fact
    rule_fields = {
        "usa.period_3y": {
            "performance start": ("period_of_performance", "start_date"),
            "performance end": ("period_of_performance", "end_date"),
        },
        "usa.obligated_95": {
            "amount obligated": ("total_obligation",),
            "potential value": ("base_and_all_options",),
        }
    }

    doc_name = "usaspending_awards"

    output = {}
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        facts = manifest["facts"].get(rule_id, [])
        result = {}
        for fact in facts:
            path = rule_fields.get(rule_id, {}).get(fact)
            if path is None:
                result[fact] = "ABSENT"
                continue

            records = index.get(entity, [])
            values = []
            for rec in records:
                val = get_field(rec, path)
                if val is not None:
                    values.append(val)

            if not values:
                result[fact] = "ABSENT"
            else:
                # For amounts, compare as Decimal to avoid float representation issues
                if fact in ("amount obligated", "potential value"):
                    decimals = [Decimal(str(v)) for v in values]
                    if len(set(decimals)) == 1:
                        result[fact] = [str(values[0]), doc_name]
                    else:
                        result[fact] = "CONFLICT"
                else:
                    # Dates and other strings: compare directly
                    if len(set(values)) == 1:
                        result[fact] = [values[0], doc_name]
                    else:
                        result[fact] = "CONFLICT"
        output[pair] = result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
