    with open(awards_path, encoding='utf-8') as f:
        awards = json.load(f)

    # Build index by generated_unique_award_id
    index = {}
    for award in awards:
        guid = award.get("generated_unique_award_id")
        if guid:
            if guid not in index:
                index[guid] = []
            index[guid].append(award)

    # Define fact extractors: field_path -> value_type
    fact_defs = {
        "usa.period_3y": {
            "performance start": ("period_of_performance.start_date", "date"),
            "performance end": ("period_of_performance.end_date", "date"),
        },
        "usa.obligated_95": {
            "amount obligated": ("total_obligation", "amount"),
            "potential value": ("base_and_all_options", "amount"),
        },
    }

    def get_field_value(record, field_path):
        parts = field_path.split(".")
        val = record
        for part in parts:
            if not isinstance(val, dict):
                return None
            val = val.get(part)
        return val

    def format_value(val, value_type):
        if value_type == "date":
            s = str(val)
            if ' ' in s:
                s = s.split(' ')[0]
            return s
        elif value_type == "amount":
            return str(Decimal(str(val)))
        return str(val)

    def values_equal(v1, v2, value_type):
        if value_type == "date":
            return v1 == v2
        elif value_type == "amount":
            return Decimal(str(v1)) == Decimal(str(v2))
        return v1 == v2

    result = {}
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        facts = manifest["facts"][rule_id]
        result[pair] = {}

        records = index.get(entity, [])

        for fact_name in facts:
            field_path, value_type = fact_defs[rule_id][fact_name]

            found_values = []
            for record in records:
                val = get_field_value(record, field_path)
                if val is not None:
                    found_values.append(val)

            if not found_values:
                result[pair][fact_name] = "ABSENT"
            else:
                first = found_values[0]
                conflict = False
                for v in found_values[1:]:
                    if not values_equal(first, v, value_type):
                        conflict = True
                        break

                if conflict:
                    result[pair][fact_name] = "CONFLICT"
                else:
                    formatted = format_value(first, value_type)
                    result[pair][fact_name] = [formatted, "usaspending_awards"]

    print(json.dumps(result, indent=2))

