from decimal import Decimal

FACT_MAPPINGS = {
    ('usa.period_3y', 'performance start'): ('usaspending_awards', ['period_of_performance', 'start_date'], 'date'),
    ('usa.period_3y', 'performance end'): ('usaspending_awards', ['period_of_performance', 'end_date'], 'date'),
