    ('usa.obligated_95', 'potential value'): ('usaspending_awards', ['base_and_all_options'], 'amount'),
}

def load_json(path):
    with open(path, 'r') as f:
        return json.load(f)

def format_date(value):
    if value is None:
        return None
    s = str(value).strip()
    if not s:
        return None
    return s.split(' ')[0] if ' ' in s else s

def format_amount(value):
    if value is None:
        return None
    s = str(value).strip()
    if not s:
        return None
    return str(Decimal(s))

def get_nested_value(record, path):
    current = record
    for key in path:
        if current is None or not isinstance(current, dict):
            return None
        current = current.get(key)
    return current

def format_value(value, value_type):
    if value is None:
        return None
    if value_type == 'date':
        return format_date(value)
    elif value_type == 'amount':
        return format_amount(value)
    else:
        s = str(value).strip()
        return s if s else None

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    manifest = load_json(manifest_path)
    pairs = manifest['pairs']
    facts_by_rule = manifest['facts']

    # Load documents and index by generated_unique_award_id
    docs = {}  # doc_name -> {entity_id -> [records]}

    for (rule_id, fact_name), (doc_name, field_path, value_type) in FACT_MAPPINGS.items():
        if doc_name not in docs:
            file_path = os.path.join(packet_dir, doc_name + '.json')
            if os.path.exists(file_path):
                data = load_json(file_path)
                indexed = {}
                if isinstance(data, list):
                    for record in data:
                        uid = record.get('generated_unique_award_id')
                        if uid:
                            indexed.setdefault(uid, []).append(record)
                elif isinstance(data, dict):
                    uid = data.get('generated_unique_award_id')
                    if uid:
                        indexed[uid] = [data]
                docs[doc_name] = indexed
            else:
                docs[doc_name] = {}

    result = {}

    for pair in pairs:
        rule_id, entity = pair.split('::', 1)
        fact_names = facts_by_rule.get(rule_id, [])

        fact_results = {}
        for fact_name in fact_names:
            mapping = FACT_MAPPINGS.get((rule_id, fact_name))
            if mapping is None:
                fact_results[fact_name] = "ABSENT"
                continue

            doc_name, field_path, value_type = mapping
            records = docs.get(doc_name, {}).get(entity, [])

            values = []
            for record in records:
                val = get_nested_value(record, field_path)
                formatted = format_value(val, value_type)
                if formatted is not None:
                    values.append(formatted)

            if len(values) == 0:
                fact_results[fact_name] = "ABSENT"
            elif len(set(values)) == 1:
                fact_results[fact_name] = [values[0], doc_name]
            else:
                fact_results[fact_name] = "CONFLICT"

        result[pair] = fact_results

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
